    {
      "card_ids": ["C10"],
      "claim": "Glafenine, the closest retrieved analogue sharing the 7-chloro-4-aminoquinoline core and an N-aryl linker, had a mean absolute oral bioavailability of approximately 0.33 in healthy volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Piperaquine, a bis-7-chloro-4-aminoquinoline antimalarial, had an estimated oral bioavailability of 0.77 in humans, supporting high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Zotepine, a structurally distant tricyclic with a dimethylaminoethoxy side chain, had absolute bioavailability of only 7-13%, a contradictory low-F example, but its low Morgan similarity to the query limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%). The closest analogue glafenine has absolute F ~33% in humans and piperaquine, another 7-chloro-4-aminoquinoline, has F ~77%; these direct human measurements outweigh the only numeric low-F evidence from structurally distant zotepine.",
  "evidence_gaps": [
    "No absolute oral bioavailability measurement exists for the exact query molecule.",
    "The closest analogue (glafenine) has only 0.34 Morgan similarity, so transfer relies on the shared 7-chloro-4-aminoquinoline core and N-aryl linker.",
    "The pyronaridine low-bioavailability report is non-quantitative and not threshold-specific, so it was not used as decisive evidence.",
    "First-pass metabolism of the dimethylaminomethyl-benzyl side chain in the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

